from matplotlib.patches import FancyBboxPatch,Polygon
ROOT=pathlib.Path('dist');OUT=ROOT/'figures';OUT.mkdir(exist_ok=True)
def read(name):return json.loads((ROOT/'data'/name).read_text(encoding='utf-8-sig'))
s=read('stations.geojson');sim=read('simulation.json');pop=read('bgri-population.json');report=read('build-report.json');dam=read('reservoir-bulletin.json');parishes=read('parishes.geojson')
plt.rcParams.update({'font.family':'DejaVu Sans','font.size':10,'axes.spines.top':False,'axes.spines.right':False,'figure.facecolor':'#f7faf9','axes.facecolor':'#f7faf9','axes.titleweight':'bold','savefig.facecolor':'#f7faf9'})
def save(fig,name):
 fig.savefig(OUT/(name+'.png'),dpi=190,bbox_inches='tight');fig.savefig(OUT/(name+'.svg'),bbox_inches='tight');plt.close(fig)
fig,ax=plt.subplots(figsize=(11,4));ax.set_xlim(0,11);ax.set_ylim(0,4);ax.axis('off')
labels=[('Chuva observada','IPMA · 1/6/24 h'),('Volume precipitado','P × área × 1000'),('Escoamento','SCS-CN · sensibilidade'),('Cheia e exposição','Hidráulica + BGRI')]
for i,(title,sub) in enumerate(labels):
 x=.2+i*2.75;ax.add_patch(FancyBboxPatch((x,1.8),2.35,1.1,boxstyle='round,pad=.12',facecolor='#e3f1ef',edgecolor='#008d94'));ax.text(x+1.175,2.5,title,ha='center',weight='bold',fontsize=11);ax.text(x+1.175,2.12,sub,ha='center',fontsize=9)
 if i<3:ax.annotate('',(x+2.64,2.35),(x+2.4,2.35),arrowprops={'arrowstyle':'->','color':'#008d94','lw':2})
ax.text(5.5,.9,'Níveis, caudais, descargas e curvas das barragens → assimilação futura',ha='center',fontsize=11,color='#9b6235');ax.text(5.5,.35,'Observação e volumes: implementados. Propagação hidráulica e mancha atual: por validar.',ha='center',fontsize=9,color='#536970');save(fig,'01_cadeia_calculo')
valid=[f['properties'] for f in s['features'] if f['properties']['p24'] is not None];top=sorted(valid,key=lambda p:p['p24'],reverse=True)[:12]
fig,ax=plt.subplots(figsize=(10,5));ax.barh([p['name'] for p in top][::-1],[p['p24'] for p in top][::-1],color='#128f9d');ax.set_xlabel('Precipitação acumulada em 24 h completas (mm)');ax.set_title('Chuva observada · maiores acumulados disponíveis');ax.grid(axis='x',alpha=.2);fig.text(.02,-.03,'IPMA · snapshot '+s['retrieved_at']+' · horas por estação conservadas; não é chuva prevista.',fontsize=8);save(fig,'02_chuva_observada')
validsim=[b for b in sim['basins'] if b['p24_mm'] is not None];topb=sorted(validsim,key=lambda b:b['rainfall_volume_m3'],reverse=True)[:10]
fig,axes=plt.subplots(1,2,figsize=(11,5));ys=np.arange(len(topb));axes[0].barh(ys,[b['rainfall_volume_m3']/1e6 for b in topb],color='#168fbe');axes[0].set_yticks(ys,["Bacia #"+b['id'] for b in topb]);axes[0].invert_yaxis();axes[0].set_title('Volume de chuva em 24 h');axes[0].set_xlabel('hm³ na área representada')
for i,cn in enumerate([55,75,90]):axes[1].barh(ys+(i-1)*.24,[b['runoff_sensitivity'][i]['volume_m3']/1e6 for b in topb],height=.23,label='CN '+str(cn),color=['#8bbba1','#13959c','#d4864b'][i])
axes[1].set_yticks(ys,[b['id'] for b in topb]);axes[1].invert_yaxis();axes[1].set_title('Escoamento · sensibilidade não calibrada');axes[1].set_xlabel('hm³ gerados; não é caudal');axes[1].legend();fig.tight_layout();fig.text(.02,-.04,'IPMA ou estimativa ECMWF, conforme cobertura. Sem propagação/descargas; volumes não somáveis entre bacias sobrepostas.',fontsize=8);save(fig,'03_volumes_escoamento')
matrix=np.array([[1,1,2,2,3],[1,2,3,3,4],[2,3,3,4,4],[2,3,4,4,5],[3,4,4,5,5]])
from matplotlib.colors import ListedColormap
fig,ax=plt.subplots(figsize=(6,5));ax.imshow(matrix,cmap=ListedColormap(['#77bfa5','#b5cb69','#e7bb42','#ec8354','#bd4869']),vmin=1,vmax=5);ax.set_xticks(range(5),range(1,6));ax.set_yticks(range(5),range(1,6));ax.set_xlabel('Intensidade da cheia');ax.set_ylabel('Consequências');ax.set_title('Referência histórica APA · REA2016');names=['Muito baixo','Baixo','Médio','Alto','Muito alto']
for i in range(5):
 for j in range(5):ax.text(j,i,names[matrix[i,j]-1],ha='center',va='center',fontsize=9)
fig.text(.02,-.02,'Benchmark histórico; a camada PGRI 2.º ciclo mantém a classe oficial publicada.',fontsize=8);save(fig,'04_matriz_referencia')
fig,ax=plt.subplots(figsize=(7,9));colors=['#dce3e4','#77bfa5','#b5cb69','#e7bb42','#ec8354','#bd4869']
for f in parishes['features']:
 g=f['geometry']; polys=g['coordinates'] if g['type']=='MultiPolygon' else [g['coordinates']]
 for poly in polys:
  ax.add_patch(Polygon(poly[0],facecolor=colors[f['properties']['risk_t100'] or 0],edgecolor='#617b7f',linewidth=.08,alpha=.75))
ax.set_xlim(-9.6,-6.1);ax.set_ylim(36.9,42.2);ax.set_aspect(1/np.cos(np.deg2rad(39.5)));ax.set_title('Freguesias · classe máxima APA T100');ax.set_xlabel('Longitude');ax.set_ylabel('Latitude');fig.text(.04,.02,'CAOP2025 + APA · fora da cobertura: cinzento. Não representa uma cheia em curso.',fontsize=8);save(fig,'05_mapa_cenario')
rows=''.join('<tr><td>'+b['id']+'</td><td>'+str(b['station_count'])+'</td><td>'+f"{b['p24_mm']:.1f}"+'</td><td>'+f"{b['rainfall_volume_m3']/1e6:.3f}"+'</td><td>'+f"{b['runoff_sensitivity'][1]['volume_m3']/1e6:.3f}"+'</td></tr>' for b in topb)
body=f'''<!doctype html><html lang="pt-PT"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>IgnispyroFloods · Relatório de implementação e estudo</title><style>body{{max-width:1000px;margin:45px auto;padding:0 24px;font:16px/1.7 system-ui;color:#17323b;background:#f7faf9}}h1,h2{{line-height:1.2}}h1{{font-size:36px}}h2{{margin-top:50px}}small{{color:#607780}}img{{width:100%;height:auto;border-radius:8px;margin:15px 0}}.grid{{display:grid;grid-template-columns:1fr 1fr;gap:20px}}table{{border-collapse:collapse;width:100%;font-size:13px}}th,td{{text-align:left;padding:10px;border-bottom:1px solid #d6e2e2}}.note{{background:#fff1db;padding:20px;border-left:4px solid #d29d42}}a{{color:#007f88}}@media(max-width:600px){{.grid{{display:block}}h1{{font-size:28px}}}}</style><a href="./">← Abrir o mapa</a><p><small>RELATÓRIO TÉCNICO · 24 OUTUBRO 2026 · V0.1 EXPERIMENTAL</small></p><h1>IgnispyroFloods<br>Da chuva à exposição humana</h1><p>Implementação de observações, cenários territoriais e simulação de volumes. Este relatório descreve o protótipo e o estudo necessário para o validar, sem apresentar resultados de validação ainda não realizados.</p><div class="note">A simulação atual calcula chuva e escoamento para condições de solo hipotéticas. Não prevê caudal de ponta, altura ou mancha de inundação atual. O risco T20/T100/T1000 no mapa é cartografia de cenário APA.</div><h2>O que foi efetivamente calculado</h2><p>{len(s['features'])} estações IPMA; {len(valid)} com acumulado completo de 24 h no snapshot. {len(sim['basins'])} bacias APA, das quais {len(validsim)} cumprem o critério mínimo de duas estações interiores sincronizadas com séries completas. As restantes ficam sem simulação, sem interpolação artificial entre bacias.</p><img src="figures/01_cadeia_calculo.png" alt="Cadeia de cálculo e etapas ainda por validar"><h2>Chuva observada</h2><img src="figures/02_chuva_observada.png" alt="Maiores acumulados observados em 24 horas"><p>Dados: {s['retrieved_at']}. As estações podem ter diferentes horas de observação; o mapa indica a hora individual.</p><h2>Volumes e escoamento</h2><p>Volume precipitado = P(mm) × A(km²) × 1000 m³. Escoamento SCS-CN com CN55/75/90 e abstração inicial 0,2S. Os três valores representam sensibilidade ao parâmetro, não quantis de probabilidade nem cenários T10/T100.</p><img src="figures/03_volumes_escoamento.png" alt="Volumes precipitados e escoamento por cenário CN"><table><tr><th>Bacia APA</th><th>Estações</th><th>P24 mm</th><th>V chuva hm³</th><th>V escoamento CN75 hm³</th></tr>{rows}</table><h2>Freguesias e população vulnerável</h2><p>{report['parishes']} freguesias CAOP2025. A BGRI2021 agrega {pop['total']:,} residentes nacionais, com crianças de 0–14 e população de 65+ anos. {report['population_matched']} freguesias têm correspondência geométrica ≥99,5% com CAOP2021; {report['population_missing']} requerem harmonização. A compatibilidade geométrica é um critério exploratório, não certificação oficial de correspondência.</p><p>No mapa, o botão de exposição consulta subsecções BGRI, recorta a freguesia e a mancha de cenário e estima residentes e grupos etários por ponderação de área, assumindo distribuição uniforme. Esse pressuposto pode produzir erro importante em áreas rurais; a investigação deverá usar edifícios residenciais e intervalos de incerteza. Crianças + 65+ são grupos etários distintos, não uma contagem completa de vulnerabilidade.</p><img src="figures/05_mapa_cenario.png" alt="Freguesias com classe máxima no cenário T100"><h2>Matriz de referência e novo estudo</h2><img src="figures/04_matriz_referencia.png" alt="Matriz histórica da APA"><p>A matriz histórica APA é o benchmark. A nova proposta deverá avaliar separadamente intensidade física, probabilidade, exposição e suscetibilidade. O protocolo no repositório define comparação de modelos, calibração por bacia, validação por evento e critérios antes de qualquer utilização operacional.</p><h2>Barragens: fontes reais, cadências distintas</h2><p>{len(dam['records'])} registos recolhidos de fontes primárias, incluindo boletim mensal SNIRH de {dam['monthly_reference']} e cinco albufeiras ARBCAS com data diária. Armazenamento e capacidade não permitem inferir a descarga. Sem afluência, descarga, curvas cota-volume e regras operacionais, a propagação nas barragens não é calculada.</p><h2>População presente e sazonalidade</h2><p>Meta Population/Movement During Crisis exige acordo de acesso; não temos dados Portugal ligados. MEO anuncia API e NOS/Vodafone oferecem produtos agregados. O formato partilhado do repositório distingue utilizadores, dispositivos, índices, pessoas estimadas e fluxos. Não se convertem automaticamente utilizadores em população nem hóspedes mensais em pessoas simultaneamente presentes.</p><h2>Reprodutibilidade e limites</h2><p>O GitHub Actions recolhe observações e recalcula volumes de 15 em 15 minutos, sujeito a atrasos; o IPMA é horário. O navegador atualiza a consulta a cada 5 minutos. Há testes de somas temporais, falhas, conservação de volumes, matriz e regras de mobilidade. Os dados originais preservam a sua data. A validação contra cheias históricas e o teste prospetivo continuam por executar.</p><p>As figuras são um snapshot da execução inicial, não um relatório vivo. As observações atuais estão no mapa e em data/simulation.json.</p><p><a href="https://github.com/dsantananet/ignispyro-floods/tree/main/docs">Artigo, protocolo, fontes e limitações no repositório ↗</a></p></html>'''
(ROOT/'report.html').write_text(body,encoding='utf-8');print(json.dumps({'figures':5,'computed_basins':len(validsim),'population_matched':report['population_matched']}))
